"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1167],{38472:e=>{e.exports=JSON.parse('{"functions":[{"name":"quantityToUrgencyText","desc":"Returns the message, text color and outline color for a given stock count.\\n\\nA `quantity` of `math.huge` means unlimited stock and yields a plain \\"In stock\\".\\nQuantities above the highest threshold fall back to \\"<n> in stock\\" in the default\\ngreen.\\n\\n```lua\\nlocal text, color, outlineColor = quantityToUrgencyText(stock)\\n\\nlabel.Text = text\\nlabel.TextColor3 = color\\nstroke.Color = outlineColor\\n```","params":[{"name":"quantity","desc":"Units remaining, or `math.huge` for unlimited","lua_type":"number"}],"returns":[{"desc":"Message, text color, outline color","lua_type":"(string, Color3, Color3)"}],"function_type":"static","source":{"line":84,"path":"src/Shared/Modules/quantityToUrgencyText.luau"}}],"properties":[],"types":[],"name":"quantityToUrgencyText","desc":"Turns a stock count into shop copy that escalates as supply runs out, along with\\nthe label colors that go with it.\\n\\nThe thresholds run from \\"50 available!\\" in green down through amber warnings to a\\nred \\"Last 1!\\" and finally a grey \\"Sold out!\\". Templates live in a frozen table in\\nthis module \u2014 edit them there to retune the wording or colors.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":14,"path":"src/Shared/Modules/quantityToUrgencyText.luau"}}')}}]);